import unittest

def compare(game, guess):
    return [abs(x-y) for x,y in zip(game,guess)]

# Unit test for function compare
def test_compare():
    class TestCompare(unittest.TestCase):

        def test_basic_case(self):
            self.assertEqual(compare([1, 2, 3], [1, 2, 3]), [0, 0, 0])

        def test_all_different(self):
            self.assertEqual(compare([1, 2, 3], [3, 2, 1]), [2, 0, 2])

        def test_guess_higher(self):
            self.assertEqual(compare([1, 2, 3], [4, 5, 6]), [3, 3, 3])

        def test_guess_lower(self):
            self.assertEqual(compare([4, 5, 6], [1, 2, 3]), [3, 3, 3])

        def test_mixed(self):
            self.assertEqual(compare([5, 1, 3, 7], [2, 8, 3, 4]), [3, 7, 0, 3])

        def test_empty_lists(self):
            self.assertEqual(compare([], []), [])

        def test_single_element(self):
            self.assertEqual(compare([10], [4]), [6])

        def test_negative_numbers(self):
            self.assertEqual(compare([-1, -5, -3], [-4, -2, -9]), [3, 3, 6])

        def test_zeros(self):
            self.assertEqual(compare([0, 0, 0], [0, 0, 0]), [0, 0, 0])

        def test_result_always_non_negative(self):
            result = compare([1, 2, 3], [10, 1, 5])
            self.assertTrue(all(x >= 0 for x in result))

    return TestCompare

if __name__ == "__main__":
    unittest.main()
